#!/usr/bin/env node
import { patchFile } from "./_patch-siman-utils.mjs";

let n = 0;
const p = (rel, slug, T) => { n += patchFile(rel, slug, T); };

p("siman_027/mechaber/part-001.txt", "mechaber", {
  "1#main": `How is the formula of kiddushin and what he should say and what he should give. It contains 10 seifim.

With money — how? He gives her in the presence of two witnesses a perutah or something worth a perutah and says to her "You are betrothed to me with this." {Rama: And some say he should say to her "according to the law of Moses and Israel" (Kol Bo) and such is the initial practice; and such is the practice to betroth with a ring and they have reason in the tikkunim of the Zohar (opinion of the Rav).} And the same if he said to her "You are my betrothed" or "You are my wife" or any language whose meaning is certainly language of kiddushin in that place, provided she understands that it is language of kiddushin; and if he had spoken with her first about matters of kiddushin and gave to her even in silence — it is kiddushin, provided they are still engaged in that matter; and all the more if he said language of kiddushin certainly but she does not understand him — it is kiddushin. {Rama: Some say we do not require that they speak in that matter specifically but rather they speak from matter to matter in that matter — for one does not speak of kiddushin except in matters of their union (Mordekhai end of "The man betroths" and likewise Rashba); and some say we do not require that he speak with her but rather whenever they speak before her it suffices (Mordekhai beginning Kiddushin and likewise implied from Tur's language).}`,
  "2#main": `If he said to her "You are my wife," "You are bound to me," "You are acquired to me," "You are my betrothed," "You are mine," "You are in my possession," "You are my purchase — betrothed" {Rama: if she understood his words or they spoke first about matters of kiddushin (Ran and Maggid Mishneh); but the man is not believed to say he did not intend for kiddushin (Beit Yosef in name of Rosh).}`,
  "3#main": `If he said to her "You are designated to me," "You are set apart for me," "You are my help," "Opposite me," "My rib," "My closed one," "Under me," "My seized one," "My grasped one" — she is betrothed in doubt. {Rama: And the same if he said "You are my betrothed (cherufati)"; but if he said to her "You are my married woman (nesuati)" some say it is nothing.} And this is when he had spoken with her first about matters of kiddushin; but if he does not speak with her first about matters of kiddushin — we are not concerned for these words. {Rama: One who said to a woman that he gives to her for love and affection — we are concerned for kiddushin for perhaps he said he gives to her that there be love and affection between them and it is as if he said to her "designated to me" or "set apart for me" (Teshuvot Mahariy end Ishut); some say that even though these languages do not help if he did not speak with her about matters of kiddushin, nevertheless if she says she accepted for kiddushin — it is doubt kiddushin (Ran); and even if he gave to her in silence and did not speak at all and she and he say they intended for kiddushin — it is kiddushin (Mordekhai chapter HaIsh Mekadesh and teshuvah Maharam); and where it is not kiddushin even if afterward he returns and says to her "You are betrothed to me" — he must return and take the money from her and give to her as kiddushin (Maggid Mishneh in name of Rashba).}`,
  "4#main": `If he said to her "You are betrothed" and did not say "to me" — she is not betrothed; and such is the essential ruling (teshuvah of Rosh); but some are stringent and say it is kiddushin (find them in teshuvah of Rashba and Ramban and Rosh kelal 36). And if he had spoken with her about matters of kiddushin — behold she is betrothed. And if he betrothed one woman first with complete kiddushin and said to another in her presence "You shall be betrothed" and did not say "to me" — presumptive evidence (meaning as one who holds the handle of a vessel pulls the vessel itself — so these matters draw after them language "to me") — we are concerned for kiddushin.`,
  "5#main": `There is one who says that when he gave her the money if he said to her "I am giving it to you as kiddushin" — it is as saying "to me." {Rama: And he must say to her language indicating for the future such as saying "They are kiddushin" or "they shall be kiddushin"; but if he said "they are kiddushin" alone — it is nothing (Beit Yosef in name of teshuvah of R' Yitzchak Doran).}`,
  "6#main": `If he said to her "I am your husband," "Behold your master," "I am your betrothed" — it is nothing even if he had spoken with her first about matters of kiddushin, because it is written "when he takes (a woman)" and not "when he takes himself." {Hagahah: One who gave money to another and said to him "Behold you are my father-in-law" and did not say "your daughter is betrothed to me" — there is nothing in this (Hagahot Alfasi first chapter Kiddushin).}`,
  "7#main": `If she gave him money and said "I am betrothed to you" — she is not betrothed.`,
  "8#main": `If he gave and she said — if he had spoken with her about matters of kiddushin — it is certainly kiddushin; and if not — it is doubt kiddushin; and if the man answered "yes" at time of giving — it is certainly kiddushin even if they are not engaged in that matter.`,
  "9#main": `If she gave and said to him "Take this dinar as a gift and betroth yourself to me" and he took it and said to her "You are betrothed to me with the benefit I received from you as a gift" — if he is an important person behold she is betrothed, for benefit has force when one enjoys from her and with this benefit she acquired herself to him; and investigation of a sage is needed — who is called a person who is not important to permit her without a get. {And some are stringent even if she did not say first when she gave "and betroth yourself to me" but only gave simply and he said to her "be betrothed" etc. and she was silent (teshuvah Rashba siman 213).}`,
  "10#main": `The measure of money with which they betroth — weight of half a barley grain of refined silver (see Yoreh Deah siman 294 seif 6 measure of worth of perutah).`,
});

p("siman_027/beer-hagolah/part-001.txt", "beer-hagolah", {
  "1#א": `Mishnah beginning Kiddushin.`,
  "1#ב": `I flagged this below siman 42.`,
  "1#ג": `As Be'er HaGolah there in the mishnah.`,
  "1#ד": `Baraitta there folio 5a.`,
  "1#ה": `Tur's language from his father Rosh there and likewise Rambam chapter 5 Laws of Marriage.`,
  "1#ו": `Mishnah 7 chapter 4 Maaser Sheni and he brings it there in Gemara.`,
  "1#ז": `As the statement of Rav Yehudah there.`,
  "1#ח": `Explanation above — they saw he spoke with her first etc. and afterward said language of definite kiddushin etc.`,
  "2#א": `Baraitta there.`,
  "2#ב": `All three in the baraitta there.`,
  "3#א": `It was asked there and not resolved.`,
  "3#ב": `Tur and likewise Rambam there and likewise Ran, and he wrote further that if she says she knew and accepted for kiddushin it is doubt etc.`,
  "4#א": `From the Gemara sugya statement of Shmuel there folio 5b and likewise Rosh and Ran and likewise Hagahot in name of Ramban and Rashba from many commentators; and R' Yerucham in Netiv 22 section 5 wrote such is essential and so appears view of Rif and Rambam.`,
  "4#ב": `Tur from his father Rosh who holds it is presumptive evidence more than nazir passing before him.`,
  "4#ג": `There in name of RaMAh from law of nazir.`,
  "5#_": `Ribash in teshuvah siman 60.`,
  "6#א": `Statement of Shmuel there.`,
  "6#ב": `There folio 6a.`,
  "7#_": `Baraitta there folio 5b.`,
  "8#א": `Tur from his father Rosh there in his rulings because it is no worse than giving to her in silence.`,
  "8#ב": `As the latter language there in Gemara.`,
  "8#ג": `There in name of RaMAh.`,
  "9#א": `Rambam's language there chapter 5 like Mar Zutra in name of Rava and as explained there.`,
  "9#ב": `Tur in name of his father Rosh there in his rulings.`,
  "10#_": `Likewise Rif from mishnah beginning Kiddushin.`,
});

p("siman_027/baer-hetev/part-001.txt", "baer-hetev", {
  "1#_": `Two. Meaning he calls two witnesses and shows them the betrothal ring if it is worth a perutah and says to them "Rav, see this ring worth a perutah" and they say yes. Derashot Maharil. And Maharam Mintz siman 109 wrote thus: he shows the ring to witnesses and warns the witnesses to see giving of the ring to the bride's finger and he betroths with his right hand and also with the bride's right hand and on the finger next to the thumb called the index finger he places the ring — see Kenesset HaGedolah. Until here Rashdam Choshen Mishpat siman 30 does not help.`,
  "2#_": `Perutah. See Sema siman 88 seif 2 — he doubts to say that in our time when one cannot buy with a perutah but only a tiny amount — we should say a woman is not betrothed with a perutah. And they do not betroth lekhatchilah with coin. If he betrothed with perutah attached to land — she is betrothed — Maggid Mishneh in name of Ran and likewise Tosafot beginning Kiddushin folio 5 in what they wrote "for thus they redeem hekdeshot" etc. and likewise Rashba siman 1026 — see in Hagahot Maharit.`,
  "3#_": `With this. And if he said to her "Take your kiddushin from atop the land" — this is doubt kiddushin — Shach in Beit Shmuel. See in Ribash siman 109. And Maharam Alsheikh siman 104. Our custom now is that he says to her "You are betrothed to me with this betrothal ring according to the law of Moses and Israel." And Maharam Trani part 1 siman 191 wrote that lekhatchilah he must say "You are betrothed to me with this ring" but bedi'eved it neither helps nor hurts — specifically when he says "You are betrothed to me"; but if he says "You shall be betrothed to me" he must say "with this." And Rashdam Choshen Mishpat siman 24 wrote even if he said nothing to her but only said to witnesses "Be witnesses for me that I give this to so-and-so for kiddushin to me" — it is kiddushin. Maharam Alsheikh siman 98 wrote: even though there is variation in the words of the witnesses — as long as there is no contradiction between them but one adds to his fellow and according to both their words there is kiddushin — we accept their testimony; and likewise Maharit part 2 Choshen Mishpat siman 38. Two witnesses — one says he said to her in holy tongue "You shall be betrothed to me with this" and one says he said to her in Greek tongue — you have no greater contradiction than this — Maharam Alsheikh siman 83.`,
  "4#_": `The Zohar. And in Beit Yosef he brought it.`,
  "5#_": `Kiddushin. Such is Tur's language. And it implies even if he said "You are betrothed to me" he must know she understands it is language of kiddushin — for not all women understand holy tongue. Likewise Bach from implication of Ran there. And Beit Yosef and Derishah and Choshen Mishpat did not hold so there — nevertheless all is according to the matter: if it is known this woman understands — it is kiddushin; and in other languages if she says she did not understand — it is doubt kiddushin lest she lies — R' Yehudah of Orleans and Bach. And Choshen Mishpat wrote she is believed and it is not even doubt. See Beit Shmuel.`,
  "6#_": `Kiddushin. Kenesset HaGedolah wrote it appears plain we require that witnesses testify he spoke with her about matters of her kiddushin. Maharival part 3 siman 61 raised to halakhah regarding one who said to a woman "Do you wish to be betrothed" and she was silent and did not answer yes or no and immediately he gave to her in silence and did not speak at all — it is doubt and we judge it as doubtful cases to be stringent. See Beit Shmuel.`,
  "7#_": `His words. If she says she did not understand — she is believed — Choshen Mishpat; and see there s.k. 5 what he wrote in name of R' Yehudah of Orleans and Bach that it is doubt.`,
  "8#_": `Believed. Beit Yosef learned this from words of Rosh who wrote these languages are clear to us — it is not in his power to say "I did not know" etc. — referring to the man who betroths; he is not believed — there. It implies specifically regarding these languages that are clear language of kiddushin — he is believed to say he did not understand; but what is doubtful to us whether it is language of kiddushin — he is believed to say he did not understand — Choshen Mishpat Beit Shmuel. Nevertheless his explanation is not compelled and Maharit in his novellae on Kiddushin explains Rosh's words otherwise.`,
  "9#_": `Nothing. This law from teshuvah of Rashba that Beit Yosef brought; and Choshen Mishpat and Beit Shmuel wrote Rashba discusses only when he did not speak with her about matters of kiddushin; but if he spoke with her about matters of kiddushin — she is certainly betrothed and not as the implication of this hagahah there.`,
  "10#_": `With her. And if he said in these languages he did not intend for kiddushin — one can say he is believed; and even per view of Beit Yosef who holds the man is not believed to say he did not understand it is language of kiddushin as written nearby — but in these languages he is believed as written s.k. 8.`,
});

p("siman_027/beit-shmuel/part-001.txt", "beit-shmuel", {
  "1#א": `Perutah. Below siman 31 s.k. 5 I wrote they do not betroth lekhatchilah with coin; and Ran wrote beginning Kiddushin and Tosafot and Rashba — if he betrothed with something attached to land it is kiddushin even though if he betrothed with document attached it is not kiddushin because we compare acquisition to release — therefore document attached is invalid like get attached; but money is not relevant to get — therefore if he betrothed with land she is betrothed. Also one can say get attached is invalid because it lacks cutting but kiddushin we hold even if it did not come to her hand she is betrothed like "give to so-and-so" — see Hagahot Maharit.`,
  "1#ב": `Worth perutah. Tosafot wrote beginning Kiddushin we derive from Hebrew slave that worth of money is like money; and in novellae of Rav Yosef Trani — if he conditioned on condition I will give such-and-such and gave worth of money against her will — it is not giving since he gave worth of money against her will. Difficult — behold Rashba wrote in teshuvah and Beit Yosef brought it siman 143 — even per one who says giving against will is giving — meaning the giver fulfilled giving; but for the recipient it is not giving for one cannot obligate her against will such as if she said give me a maneh and I will betroth myself to you and he gave against will — it is not kiddushin; per this even if he gave money and not worth of money it is not kiddushin since she did not consent. And possible there discusses when she conditioned the condition "give me a maneh" — then we say giving against will is not giving; but when he conditioned on condition I will give you — then even against will it is giving for he conditioned the condition; nevertheless afterward wrote in Maharit even in such case it is not giving. And see siman 143 there explained giving against will — Rosh holds it is doubt get; and Rambam holds it is rabbinically invalid; and presumably likewise in kiddushin this dispute applies. And apparently from Rosh's words chapter 4 what he wrote — he holds even giving against will and worth of money is doubt — for he wrote in the sugya there if he conditioned she will give a coat — coat specifically he says and not money for the coat; and reason is we say the husband intends to pain her; and Rosh wrote if she consented to take money it is giving — we learn the sugya discusses giving against will; nevertheless if he did not intend to pain — it is giving — we learn even giving against will and worth of money helps; however per what is written siman 143 there is no proof from Rosh — see teshuvah Mahara ben Sasson siman 65 and Choshen Mishpat siman 241 seif 7; and there is more to bring proof giving against will and worth of money is giving from Hebrew slave — except there in the novellae he rejects this proof and wrote Hebrew slave is different for Torah doubled the law; and apparently his words are wondrous for if so from where did Talmud beginning Kiddushin learn from Hebrew slave worth of money is like money.`,
  "1#ג": `And says to her. And if he said "Take your kiddushin from atop the land" — behold this is doubt kiddushin — teshuvah Shach.`,
  "1#ד": `You are betrothed to me. Tosafot wrote beginning Kiddushin — "to me" meaning to be mine; therefore "You are betrothed to me" is language of sanctification upon all people for my sake as if he said "You are betrothed and forbidden to all the world for my sake."`,
  "1#ה": `That she understand. Such is Tur's language — implies even if he said "You are betrothed to me" he must know she understands it is language of kiddushin — for not all women understand holy tongue; and likewise implied in Ran and Maggid and likewise Bach and not like Beit Yosef; nevertheless it appears all is according to the matter: if it is known this woman understands — it is kiddushin; and in other languages if she says she did not understand — it is doubt kiddushin lest she lie — and likewise R' Yehudah of Orleans and Bach. And what Rosh wrote — these languages are clear to us they are language of kiddushin — it is not in his power to say "I did not know" — one can explain his words: she is not believed to uproot kiddushin entirely but it is doubt; and this is what Tur wrote "provided she understand" — for where she would certainly be betrothed to him.`,
  "1#ו": `Spoke with her. Rambam wrote chapter 3 law 1 — he spoke with the woman about matters of kiddushin and she consented and he stood and betrothed etc.; and Kesef Mishneh wrote specifically that she said yes but silence does not help; nevertheless from other poskim it does not appear so and likewise from Hagahot Maimoniyot end Gittin as written nearby in hagahah — when they speak before her it suffices — we learn even if she was silent it helps; and one can say likewise for Rambam if she was silent it is consent. Also in Hagahot Maharit he challenged Kesef Mishneh; and per all specifically when they speak about matters of her kiddushin — see teshuvah Mahari of Lublin siman 2.`,
  "2#_": `But the man is not believed. Beit Yosef wrote Tur learned this from Rosh who wrote these languages are clear to us — it is not in his power to say "I did not know" — and he understood Rosh refers to the man who betroths — he is not believed he did not understand; and specifically regarding what is clear to us it is language of kiddushin he is not believed to say he did not understand; but what is doubtful to us whether it is language of kiddushin — he is believed to say he did not understand; nevertheless his explanation is not compelled and Maharit explains Rosh's words otherwise.`,
  "3#א": `You are my married woman etc. Rashba wrote in teshuvah — if he said "You are my married woman" it is not like "You are my wife"; nevertheless one can say it is still doubt kiddushin; and what he wrote it is not like "You are my wife" — meaning it is not definite kiddushin. And one can compare to saying for love and affection as written nearby; and likewise Taz. And all this discusses only when he did not speak with her about matters of kiddushin; but if he spoke with her about matters of kiddushin — she is certainly betrothed; and likewise in Hagahot Maharit and Bedek HaBayit — until here Gemara does not discuss except languages that can be interpreted for work or other matter; but "my married woman" does not imply any other meaning — if so when he spoke with her about matters of kiddushin she is certainly betrothed; and likewise Choshen Mishpat and not as implication of this hagahah.`,
  "3#ב": `And this when he spoke with her etc. And if he said in these languages he did not intend for kiddushin — one can say he is believed; and even per view of Beit Yosef who holds the man is not believed to say he did not understand it is language of kiddushin as written nearby — one can say these languages are different for Gemara doubts whether they are language of kiddushin — he is believed to say he did not intend for kiddushin; and likewise Choshen Mishpat.`,
  "3#ג": `For love and affection etc. Meaning language he said for love and affection is as if he said on condition there be love and affection between them and it is no less than saying "set apart for me"; and if both their intent was for kiddushin — get is needed — likewise Mordekhai. And it appears his intent — even if he spoke with her about matters of kiddushin even though it is not meaning for work — nevertheless since he said for love and did not say there be love between them — it is as if he said he gives to her for love that already exists between them — therefore it is only doubt kiddushin even if he spoke with her about matters of kiddushin. And one can disagree regarding saying "You are my married woman" as I wrote nearby — if he spoke with her about matters of kiddushin she is certainly betrothed.`,
  "3#ד": `And some say that even etc. Likewise Ran; nevertheless from Rambam and Rosh it appears they disagree with Ran and hold in these languages there is nothing even doubt kiddushin when they were not engaged in matters of kiddushin even if they intended for kiddushin; and likewise R' Yehudah of Orleans explicitly and likewise Hagahot Maharit; and apparently it appears from Gemara not like Ran — for even in languages clear to us that are language of kiddushin nevertheless we require she understand it is language of kiddushin or they spoke about matters of kiddushin as Ran and other poskim wrote — if so why did Gemara challenge on the languages that Gemara doubts whether they are language of kiddushin or not — in what are we dealing? Shall we say when they did not speak about matters of kiddushin — from where would she know? Teach even in languages that are certainly language of kiddushin this difficulty is also difficult — in what are we dealing? Rather perforce must say there for a different reason — for one can say it discusses she understands it is language of kiddushin; but in these languages it does not help even if she understands. And likewise implied from Tur; and in these languages that we doubt whether they are language of kiddushin and they were engaged in matters of kiddushin and both say their intent was for kiddushin — he wrote it is doubt kiddushin since we doubt — likewise the witnesses doubt and it is as if there were no witnesses in the matter.`,
  "3#ה": `And even if he gave to her in silence. Likewise Mordekhai end chapter HaIsh Mekadesh; but it does not appear from words of other poskim — see teshuvah Rashba siman 574 and Ritva that Beit Yosef brought siman 45 and in Maggid and teshuvah Rashdam siman 34; and already elaborated on this in Choshen Mishpat; nevertheless if there was already consent between them and afterward he gave to her in silence — one can compare to gifts as written siman 45 per view of Rashi who is concerned in gifts that he gives for kiddushin even though he does not speak with her at all; and likewise in Maggid there.`,
  "3#ו": `Must return and take the money. Below in chapter 5 Gittin explained — he gave her the get and it was not valid giving — he need not return and take the get from her and give anew but says to her "Here is your get" unless when she was partially divorced from the first giving — then he must take from her and give to her; but if she was not divorced at all from the first giving — he need not take from her. Difficult — why need here to take kiddushin from her? Behold in the first giving she was not betrothed at all; and likewise explained below siman 30/31 as written there in name of Rashba — if they did not place the kiddushin he need not take from her; and requires examination — Taz.`,
  "4#א": `But some are stringent. Likewise in books Beit Yosef in name of Rashba; but Ribash in teshuvah siman 266 wrote in name of Ramban and Rashba who hold whoever did not say "to me" there is no concern; and likewise Maggid and in teshuvah Beit Yosef and Bedek HaBayit wrote these teshuvot in name of Rashba that it is kiddushin — they do not rely on them; and likewise Hagahot Maharit; and even per the stringent — nevertheless if there is additional closeness or where it is only doubt kiddushin even if he said "to me" they are lenient there in teshuvah folio 7; and if he did not say "to me" they agree their intent was for kiddushin — be stringent — teshuvah Rashdam siman 34; and likewise Beit Yosef explained teshuvah Rashba siman 574; see teshuvah Mahari of Lublin; and if there was matchmaking between them — ruled in teshuvah Ben Lev part 3 it is like presumptive evidence; and Hagahot Maharit disagrees.`,
  "4#ב": `And we are concerned for kiddushin. Meaning doubtful kiddushin — for one can say since he already betrothed one for himself he betrothed this one for his fellow — likewise Beit Yosef. Also one can say the doubt is per the girsa as Tosafot wrote there.`,
  "5#א": `As kiddushin. The reason explained in Beit Yosef in name of Ribam — since it is mentioned he gives to her as kiddushin it appears from his language he is the one who betroths and she is betrothed even if he is agent for another and she agent for another — we say a person does not abandon what is incumbent upon him; and if he said "I give to you for kiddushin" Hagahot Maharit wrote there is no concern of kiddushin — for one can say he gives for need of kiddushin and does not betroth with it. And one can disagree regarding saying "as kiddushin" — for there he reveals his intent in this giving that she is betrothed; nevertheless in teshuvah Rashba wrote if he said "I give to you for kiddushin" it is as saying "to me"; if he said "Take this ring kiddushin for your daughter" — it is not kiddushin; and one can disagree regarding saying "as kiddushin" since he did not say "I give to you."`,
  "5#ב": `It is as saying to me. It implies it is definite kiddushin — in teshuvah Rashba siman 574 wrote it is doubt; and likewise implied from teshuvah Ribash siman 266; see teshuvah Mahari mentioned.`,
  "5#ג": `They are kiddushin is nothing. And such we rule below siman 141 regarding nullification of get — must say language for the future; and if he says "this get is pottery" it is not a get; and presumably we compare kiddushin to divorce — per this must say what is written nearby for love and affection it is kiddushin — meaning he says language for the future; nevertheless Choshen Mishpat wrote kiddushin is language of sanctification and in sanctification it is sanctification — therefore be stringent in kiddushin; and if they spoke at first about matters of kiddushin it appears to be stringent.`,
  "6#א": `Even if he spoke. Rosh and Tur ruled so; nevertheless R' Yehudah of Orleans is stringent and wrote in name of some say it is definite kiddushin and some say doubt; and likewise teshuvah Mahari is stringent.`,
  "6#ב": `Behold you are my father-in-law etc. The reason because it is written "when he takes a woman" and not "when he takes himself" — even though the father is the one who transfers nevertheless he must transfer his daughter and not himself; and if he hints he betroths his daughter it does not help for language must be clear — there in the novellae; and even if they spoke about matters of kiddushin it is nothing; and Choshen Mishpat wrote great doubt practically even if he did not speak with him about matters of kiddushin — all the more if he spoke with him.`,
  "7#_": `She gave etc. And it does not help even if they spoke about matters of kiddushin for it is written "when a man takes" and not "when she takes" — even though if they speak about matters of kiddushin it is as if he said; nevertheless when she gave and she said and they were engaged in matters of kiddushin it is as if she gave and he said — per this if he is important person and they were engaged in matters of kiddushin and she said and she gave — it is certainly kiddushin for what they were engaged in matters of kiddushin is as if he spoke and important person is as if he gave; nevertheless in Tosafot in this sugya it does not appear so; also in Perishah wrote she is not betrothed.`,
  "8#א": `It is doubt. Likewise Rambam; nevertheless Rif wrote we are concerned rabbinically — implies it is not biblical kiddushin; and likewise Rosh and Ran and R' Yehudah of Orleans — concerned rabbinically; but when they speak about matters of kiddushin it is as if he said and he gave and it does not matter that she also speaks.`,
  "8#ב": `And if the husband answered yes. Bach wrote — meaning they spoke about matters of kiddushin; and I say rather what he answered is as speaking about matters of kiddushin; and what Bach wrote if they did not speak about matters of kiddushin — one can say what he said yes is as no for there is yes that is as no; I say for if so why does it help if he betrothed through robbery and she said yes; also in Derishah wrote in name of Maharshal even if they did not speak about matters of kiddushin behold she is certainly betrothed.`,
  "9#א": `Who is called a person who is not important. It implies ordinary people are called important; and in teshuvah Rashba wrote ordinary people are called not important; see Choshen Mishpat siman 190 — if he said "Take a maneh and field sold to you" he acquires provided he is important person; one can say there the acquirer must know he is important person — likewise in Perishah.`,
  "9#ב": `And some are stringent. Majority of poskim hold so — likewise Rosh and Ran and R' Yehudah of Orleans and Maggid wrote in this sugya in "she gave and he said" it is kiddushin even if she did not say "and betroth yourself to me" for this sugya does not discuss she said; and likewise appears from Tosafot; see teshuvah Rashba there explained when she did not say "and betroth yourself to me" it is doubt even if he spoke with her about matters of kiddushin lest she does not want to be betrothed to important person; and per view of Hagahot Maimoniyot even person who is not important it is kiddushin; also Ran brought words of Hagahot Maimoniyot and Bach is stringent as view of Hagahot Maimoniyot and wrote practically needs settlement.`,
});

p("siman_027/beur-hagra/part-001.txt", "beur-hagra", {
  "1#_": `In the presence of two. Mishnah 1 chapter 65 law 1.`,
  "2#_": `Perutah etc. As Be'er HaGolah and mishnayot chapter 4 Bava Metzia and entire sugya of Gemara.`,
  "3#_": `And said to her behold etc. Chapter 2. With this — Rambam's language and as written siman 46 law 47 and end of chapter.`,
  "4#_": `And some say. Tosafot Ketubot 3a s.v. ade'ata and Gittin 33a s.v. kol and likewise explicitly in Yerushalmi.`,
  "5#_": `And there is all. Beginning tikkun 5.`,
  "6#_": `And the same etc. Baraitta and statement there chapter 2.`,
  "7#_": `And likewise in every etc. Tur's language and likewise in Rambam except Rambam did not write it in that place and it is taken from Rosh's words; and he learned from what is written "one who says my betrothed in Judah" etc.; but Rambam follows his view that cherufati is betrothed everywhere and as girsa of R' Chananel who does not have all the back-and-forth but only "one who says my betrothed is betrothed" — for in Judah they call betrothed cherufah since it is language of kiddushin; but per our books even doubt kiddushin is not in other places even though cherufah is doubt because it is doubt language of kiddushin everywhere — end of seif.`,
  "8#_": `Provided. Rambam and Tur and likewise Rashba — what it challenges "in what are we dealing" etc. refers to all languages even "my purchase" and "bound to me" not like Be'er HaGolah; and Rosh explained it refers only to language they doubt; and proof from what is written about matters of her get — and in get it is not asked there at all; but Tur holds like Rosh alone in cherufati he also explains these doubts in "matters of" etc. refer; but those that are doubtful at first but certainly he holds like Rosh — as he wrote; and all the more if etc. — end of seif 2.`,
  "9#_": `And if he was etc. There Apsik halakhah like R' Yosi.`,
  "10#_": `And this etc. Be'er HaGolah and Tur and Ran like statement of Shmuel and R' Oshaya and further that chapter 5 like his fellow.`,
});

p("siman_027/beit-meir/part-001.txt", "beit-meir", {
  "1#_": `And provided she understand — Beit Shmuel wrote and it implies etc. and likewise implied in Ran and Maggid and likewise Bach and not like Beit Yosef — see in Beit Yosef for per their view their meaning is like Beit Yosef except Bach wrote "provided she understand" refers only to what he concludes "in every language"; and Ran and Maggid strained themselves to change their intent; and essential is like Beit Yosef except Choshen Mishpat wrote plainly to be stringent if she accepted kiddushin from another because she made herself available; and through this possible if she returns with excuse she is believed.`,
  "2#_": `{Hagahah} But the man is not believed — Choshen Mishpat wrote from Rosh's words etc. Truth per Beit Yosef's explanation in Rosh one can infer thus: since he wrote in definite languages he is not believed — implies in doubtful ones he is believed; and if so compelled also in doubtful ones even if engaged and spoke about matters of kiddushin and afterward said doubtful language also believed to permit; and likewise Beit Shmuel s.k. 9 in his name for he concludes "and all these doubts when he spoke with her about matters of kiddushin; and if not there is no substance"; and implied also from him even if she says she accepted for kiddushin; and if so likewise if both say they intended for kiddushin there is no substance; and if so why would his credibility help in doubtful language or his intent in doubtful languages even if they spoke about matters of kiddushin he is believed; but I wonder if for this Choshen Mishpat intended — from where did he learn he is believed to explain his words he did not intend only for work; and just as she is believed on definite languages to say she did not understand — so he is believed to explain the doubts; and let us say conversely — behold we see Rama wrote seif 2 on definite languages discusses when they did not speak first — if she understood his words to teach that if she says she did not understand she is believed; and in seif 3 on doubtful language discusses when they spoke — we do not hear anyone say if she claims she did not understand and thought he retracted and spoke for work she exits from doubt and is better than giving to her in silence — we learn clearly here all agree he is not believed; and if so let us also say here he too is not believed since he spoke first about matters of kiddushin; and perhaps one can strain that specifically she who is presumed not to know at all what he said per Gemara's question — and it is found she is presumed not to understand neither for kiddushin nor for work — therefore regarding her there is substance like giving in silence; unlike him who knows what he says and we doubt — he has in his hand to explain; but requires examination for if so the matter depends on him whether to permit or forbid and witnesses cannot forbid her if she permits — it would be like betrothing without witnesses — see below.`,
  "3#_": `{Hagahah} For love and affection — Beit Shmuel wrote and it appears his intent etc. does not mean this is Choshen Mishpat's explanation of Maharam's words "it is no less" — rather he explained his intent: although no less nevertheless also not better; and let us not say if they spoke first since language is not for work she is certainly betrothed; and he wrote here too one can doubt even with prior speech.`,
  "4#_": `And even if he gave to her in silence — see Choshen Mishpat wrote in one opinion although it can be resolved with strain — per my view there is no strain; and conversely there is somewhat proof from here specifically he gave and she said is doubt even if he says he did not intend in his silence for kiddushin he is not believed and she is betrothed from doubt; unlike when all is in silence even in category of doubt it is not unless they say they intended; and then possible even certainly betrothed; and proof — in he gave and she said Ran explained we consider her statement to bring to doubt regarding his intent in the giving lest he intended for kiddushin similar to speaking first; at least we hear from this; and also from giving in silence and they spoke first — giving silence and accepting silence helps if their thought is known through collateral meaning through they spoke first certainly; and through her statement for doubt; and one can learn likewise if both explain intent was for kiddushin one can say she is certainly betrothed; and what he wrote from reason matters of the heart — Maharam himself wrote since it does not contradict his speech nor his act it is only explanation of the act and it is words; also in language of Maggid Mishneh in Beit Shmuel who wrote if they were not engaged at all and he gave her money simply she is not betrothed even if he says he intended to betroth her — possible to strain specifically his statement alone does not help if she says she did not intend; but if both say they intended one can say he admits nevertheless; after all from proofs of Choshen Mishpat compelled in giving silence without their speech even doubt is not found for all kiddushin are only by their mouths — like betrothing without witnesses; granted in he gave etc. immediately for witnesses at least doubt she was betrothed in doubt before witnesses; but here as said; and as explained in teshuvah Rashba in Beit Shmuel and likewise siman 1033; and per my view this is also reason for implication of poskim disagreeing with Ran in Beit Shmuel s.k. 11 who hold in doubtful languages when they were not engaged even if she says intent also no concern though Gemara's question supports Ran — for it only challenged from where would she know — implies if she knew she is betrothed; except they reason since it decided from where would she know — implies no doubt lest she knew; and even witnesses per this are not doubtful — automatically even if she says she knew it is nothing for she was not betrothed without language; and this is also Beit Shmuel's intent concluding that s.k. "and in these languages that we doubt" (he wrote) it is doubt; and per my view must say (it appears) it is doubt for I did not find to whom he alludes; and correct as he concludes "and it is as if there were no witnesses in the matter" — meaning on definite and Ran's view in Shulchan Aruch in name of "some say" with Maharam's understanding of Rama — requires examination how they divide between betrothed without language and Beit Shmuel s.k. 12 concludes nevertheless etc. and likewise in Mordekhai; and the question in Mordekhai plainly appears as we understood Rama for thus he wrote but here discusses he spoke when he gave to her for love and affection and this language has language of gifts — we are concerned for gifts; and all the above he wrote on beginning of his placement in this language per witnesses who did not examine her words whether she consented first to be betrothed to him for this — he decreed even though at time he gave they did not hear from his mouth then certainly needs get; and what is written there first hagahah (and both agree intent was for kiddushin of betrother and betrothed) — therefore it is not fitting for comparison to gifts explained siman 45 that even if both say they did not intend they are not believed; but afterward he wrote if there are no witnesses she consented except both know she accepted and she admits she consented before — needs get; and again wrote or even if he did not speak with her at all but only at time he gave her it was in his heart for kiddushin and she too accepted for kiddushin; and Rama understood from his latter words if there are no witnesses she consented meaning not matchmade and no concern of gifts per Rashi — then the difficulty came upon him from reason she admits she consented and in any case there are witnesses he said to her for love and affection which is language of gifts — needs get; and this too nevertheless from reason of gifts; and what is written "except both know she accepted" — meaning the two witnesses though they are not witnesses at all on consent nevertheless since they know from acceptance and they admit she consented meaning similar to matchmade — then concerned for gifts per Rashi except he again wrote or even if he did not speak at all meaning even if he did not speak with her beforehand she will consent for kiddushin — found no concern of gifts per Rashi; therefore difficulty came only at time etc. meaning they admit this intent; and therefore she needs get through their admission; and from this Rama copied; but requires examination as said; and all the more teshuvah Maimon siman 1 Maharam himself writes but in this case there are no witnesses etc. until he concludes except we learn no distinction between admission and non-admission except in witnesses and their sight everything depends; and perforce must admit that word "or" in Mordekhai is error and all refers in any case to both knowing they consented originally — then because of stringency of they were engaged in that matter and also even if not from matter to matter nevertheless concern of gifts applies unless we strain specifically on essence of kiddushin meaning giving to her hand he was strict admission without language does not help; but where there are witnesses on giving though without their admission it is nothing nevertheless not uprooted from betrothal with witnesses after body of giving is with witnesses — included matter from money; and similar in Ran mentioned; therefore to strain thus requires examination.`,
  "5#_": `{Hagahah} Must return and take the money — see Beit Shmuel and see Maggid Mishneh chapter 1 Laws of Divorce law 3 wrote here because of doubt lest he gave to her as gift he must return and take it.`,
  "6#_": `{Hagahah} As kiddushin — see Beit Shmuel and at end concludes and one can disagree saying "as kiddushin" for he did not say "I give to you" — meaning unlike when he said "I am giving to you" which is as saying I; and if so one can also disagree saying "behold it is yours for kiddushin" for also he did not say I; see end Hagahot Mordekhai Gittin and in Darkei Moshe here wrote he disagrees with Ribash; and per what I said it is not compelled; see siman 37 in Tur teshuvah Rosh regarding one who said "Take kiddushin for your daughter" and siman 32 seif 4.`,
  "7#_": `It is doubt — see Beit Shmuel and see Peri Chadash Yoreh Deah siman 110 beginning of kelalim s.s. s.v. ve'ata batra; and per Ran's understanding in Rif doubt is not precise and from Torah she is not betrothed; and he strained himself in his reason; and likewise understood R' Yosef Trani — one can say he learned from challenge of first chapter folio 4b in Tosafot s.v. heikhi dami from their words "when he takes" comes only to exclude he gave and she said — these are doubtful language in Gemara not precise but rabbinic concern because somewhat similar to "when he takes" and it appears in doubt.`,
});

p("siman_027/chokhmat-shlomo/part-001.txt", "chokhmat-shlomo", {
  "1#_": `Seif 1 — he said to her "You are betrothed to me" etc. NB see in Yeshuot Yaakov who brought proof from Yerushalmi that pilegesh is in kiddushin; and see in my composition Mizbach Avanim on Avodah Zarah edition 9 siman 76 Laws of Marriage siman 15 what I rejected this proof — may God help examine.`,
  "2#_": `Seif 2 — he said to her "You are my wife" etc. NB I present here one detail of what is difficult for me with God's help in sugya of chuppah acquires in words of Tosafot there s.v. af ani bring chuppah etc. even though he hands his minor daughter to chuppah against her will since it refers to his daughter it is not considered against her will — end quote for our matter; and I wonder greatly for he contradicts explicit sugya Gittin chapter 2 (folio 21a) that says there and alternatively agency for receipt we also find against her will for thus father receives get for his minor daughter against her will — behold explicit it is considered against her will even where it refers to his daughter — requires great examination.`,
  "3#_": `Seif 8 — he gave and she said etc. and if not it is doubt kiddushin etc. NB in Gemara it says and we are concerned rabbinically — see in Ran and see in my novellae to Laws of Gittin siman 141 seif 1 in my edition zayin siman 82 what I wrote on this — may God help examine.`,
});

p("siman_027/pitchei-teshuva/part-001.txt", "pitchei-teshuva", {
  "1#_": `Perutah — Ba'er Hetev wrote see Sema etc. and it is from Choshen Mishpat s.s. this that they brought; and see in Sefer Avnei Meluim s.k. 20 what he wrote on this. And what Ba'er Hetev wrote they do not betroth lekhatchilah with coin — from Beit Shmuel here and below siman 31 s.k. 5; and there he wrote this in name of Mordekhai; see in Sefer Avnei Meluim s.k. 2 who wrote in Gemara it implies they betroth with coin and in Mordekhai he did not write this except as investigation — requires examination how they betroth with coin; let us also say her mind is imprisoned and it is void; but already they wrote to distinguish between law of money and law of exchange (see first chapter beginning Kiddushin and in Beur HaGra siman 32); and in Sefer HaMakneh part 1 he produced reason for Beit Shmuel's words they do not betroth with coin — see there; nevertheless from Beit Shmuel's words it appears he intended this for Mordekhai wrote regarding her mind is imprisoned; and per what he wrote also Mordekhai holds they betroth with coin — end quote see there (and what Ba'er Hetev wrote s.k. 1 "and he betroths with his right hand and also bride's right hand and on finger" see in Sefer Kerem Shlomo in teshuvot at end of book siman 86 who wrote must be careful there be no interposition between ring and finger — therefore if bride wears gloves she must remove from her right hand — see there).`,
  "2#_": `Or worth perutah (in margin Shulchan Aruch the Gaon Ra'ak Eiger z"l NB in Rashba's novellae chapter Kol HaNishba'in he doubts if he betrothed with utensils — one can say need not be worth perutah like regarding oath in Choshen Mishpat siman 88 seif 3 end quote; see in Ketzot HaChoshen Choshen Mishpat there s.k. 3 who also brought Rashba's words and wondered on him; and in Sefer Nehora HaM'ar there he settled his wonder — see there; and on siman 31 seif 3): and Beit Shmuel wrote and Hagahot Maharit wrote if he conditioned on condition I will give such amount and gave worth of money against her will it is not giving since he gave worth of money against her will; difficult — behold Rashba wrote etc. see there; see in Sefer HaMakneh part 1 what he wrote on this and concluded there therefore it appears in every case it is doubt betrothed — see there; and see in Sefer Avnei Meluim s.k. 4 what he wrote on this; and see further in Sefer Yad HaMelekh chapter 3 Laws of Marriage halakhah 1 on this matter.`,
  "3#_": `To me with this. Ba'er Hetev wrote and if he said to her "Take your kiddushin from atop land" — this is doubt kiddushin; see in Sefer HaMakneh part 1 his view it is certainly kiddushin and he brought in teshuvah Shach siman 252 and in teshuvah Maharival they also wrote this law is like attached to land for one reason — see there; and in Sefer Get Mekushar part 1 letter 10 who elaborated greatly on this law and his view there in kiddushin of money even if he said take from atop land she is properly betrothed; but in kiddushin of document there is room to doubt — see there (and see in teshuvah Chasam Sofer siman 82 who sided in his case to nullify kiddushin because ring was already in her hand as gift and it is take your kiddushin from atop land per Maharil in teshuvah siman 78 brought also in Ba'er Hetev siman 30 s.k. 8) — plainly in his eyes take from atop land she is not betrothed for acquisition is compared to release; and he wrote we do not abandon Maharil's plain meaning because of doubt of later geonim who did not see his words and if they had seen they would retract; and per my humble opinion without doubt betrothing with document we compare to divorce document invalid on it etc. and automatically invalid also in money for acquisitions are compared to each other as explained plainly in Ketubot 74 etc.; but what Maharil wrote there to distinguish betrothing with deposit in her hand as Beit Shmuel wrote siman 30 has no understanding; and per my humble opinion to explain per what Tosafot Bava Metzia 6a s.v. hekdishah etc. — if so here too initially when deposited in her hand her hand was hand of depositor and when he betroths her he removed his power from her and her hand became her own hand and it is as handing from his hand to her hand; and likewise proven in get itself end chapter HaMevi — even if we say depositor places get in wife's hand and afterward said be divorced — it is take your get from atop land; one can say this is depositing get which is document for it is diminished from law of guardians and her hand did not become like his hand except if she is agent her hand becomes hand of sender etc.; but in kiddushin of money his deposit helps for hand of guardian is like hand of owner and when he removes his hand she is betrothed etc.; and per this in the case where it was hers as gift she did not become guardian and even in place where they return in death and divorce nevertheless for others she is not obligated; and if so since her hand never became like his when he betroths her it is take from atop land; but requires examination from Rosh's words in the case he betrothed with gold plate Kiddushin 12 etc.; and possible to distinguish between money and object for with money waiver suffices etc.; nevertheless although we compare we do not act to permit on this heter alone; but in any case see to combine etc. end quote see there further siman 101 from this and on s.k. 12): and what Ba'er Hetev further wrote our custom now etc. see in Sefer HaMakneh part 1 below seif 5 who wrote it appears from language of Shmuel (in Gemara folio 5b) must say "betrothed to me with this money" and what we practice to say with this ring is for enhancement of the matter; and even with document of kiddushin it appears in sugya folio 9 need not write in it "You are betrothed with this document" — see there (also in teshuvah Chasam Sofer s.s. 107 wrote must say with this object; and view of Rav Nathan in his commentary end Gittin must say with this object — unique view etc. see there; and there s.s. 85 brought in teshuvah Rama wrote one who gives her utensil and says with this ring betrothed; and in teshuvah Shev Yaakov wrote on him meaning if both want kiddushin; but where they say their intent was jesting and he said ring on object — act proves matters of heart all was jest and play — see there; and on what I wrote siman 31 s.k. 7).`,
  "4#_": `That she understand. See in teshuvah Noda BiYehudah siman 59 who wrote it appears to him what Shulchan Aruch wrote "provided she understand" etc. — meaning if she says she did not understand she is completely believed and there is no kiddushin at all; and as Choshen Mishpat wrote such is implication of all poskim and not like Beit Shmuel s.k. 5 who wrote it is doubt lest she lies — meaning why not believe her since there is no presumption of prohibition; Rava has presumption of permission supporting her certainly believed etc.; and perhaps since language is clear her claim to say she did not understand — see there; and on what is written below siman 42 s.k. 3.`,
  "5#_": `About matters of kiddushin. Maggid Mishneh wrote chapter 3 Laws of Marriage law 7 and thus: no difference whether they spoke about matters of kiddushin for himself or about matters of kiddushin for his fellow such as he appointed agent and gave her kiddushin and did not explain so — likewise Maharit in teshuvah Choshen Mishpat siman 12 — see there.`,
  "6#_": `If she understood his words. See in Sefer Avnei Meluim s.k. 6 who wrote it implies even if witnesses do not know if she understood — whenever she says she understood it is definite kiddushin; difficult for behold it is like betrothing without witnesses; and possible since essence of kiddushin is from side of betrother as Ran wrote Nedarim folio 50 etc. therefore does not require two witnesses except for body of kiddushin they heard from betrother; but woman's will does not require witnesses and her admission suffices; and still requires examination — see there end quote; and see in Sefer Tiv Kiddushin s.k. 10 who also stood on this for behold it is like betrothing without witnesses; and he wrote thus: and possible here discusses she said in that same session when witnesses asked her she accepted for kiddushin — matter was revealed she knew at time of giving; but after time possible in truth since she can say she did not understand it is like betrothing without witnesses; nevertheless since there is doubt immediately at time of kiddushin lest she understood possible it is doubt etc.; however in her saying afterward she did not understand one can say since she was not established we believe her to clarify the doubt etc. end quote; and see in his words siman 58 s.k. 44 he also derives from this.`,
  "7#_": `You are designated etc. See in Sefer HaMakneh part 1 s.v. 66 who wrote it appears in these languages Gemara doubts even if he said two languages together (meaning clear language and doubtful language) — he said "You are my wife" and "my help" — one can say it is doubt kiddushin; not to mention when he betrothed with one perutah it is like "your daughter and lands" with perutah — here too one can doubt regarding work it is like for kiddushin and work; rather even when he betroths with two perutot one can say it resembles "acquire you and donkey" — giving money does not help for work and further she did not intend for work and also did not consent to kiddushin except with all the money — end quote.`,
  "8#_": `You are my married woman — some say it is nothing. See in Sefer HaMakneh part 1 who wrote it appears where kiddushin and nissuin come as one such as he brought her into his house and betrothed her as explained below siman 33 in hagahah; and likewise per Maggid Mishneh who wrote above (will be brought below siman 61 s.k. 1) if he brought her to chuppah and afterward betrothed her she becomes married at time of kiddushin; and in such case language "my married woman" applies more than "my betrothed"; and relevant are documents of nissuin (meaning this is Gemara's intent Kiddushin folio 9b documents of nissuin — if he wrote in document "You are my married woman" as I wrote siman 33 end quote).`,
  "9#_": `We are not concerned for these words. See in Sefer Avnei Meluim s.k. 8 regarding document — if he wrote in document of kiddushin these languages — see there.`,
  "10#_": `Or set apart. Ba'er Hetev; and see in Maggid Mishneh chapter 3 Laws of Marriage law 7.`,
});

p("siman_027/rabbi-akiva-eiger/part-001.txt", "rabbi-akiva-eiger", {
  "1#_": `Siman 27 seif 1 or worth perutah. NB in Rashba's commentary Shevuot chapter 4 he doubts if he betroths with utensils — one can say need not be worth perutah like regarding oath in Choshen Mishpat siman 88.`,
  "2#_": `There or worth perutah. NB he betrothed with document — see Yerushalmi Nedarim chapter 5 halakhah 5 and in Korban HaEidah there.`,
  "3#_": `There you are betrothed to me with this. NB if he did not say "with this" — see teshuvah Maharit part 1 siman 191 that it helps; and he distinguishes there if he said "You shall be betrothed to me" it does not help unless he said "with this"; see teshuvah Kol Eliyahu Even HaEzer siman 5.`,
  "4#_": `There hagahah to betroth with ring. NB and if he said "You are betrothed to me with this ring." And it was a cup — see below siman 38 in Beit Shmuel s.k. 47; see in teshuvah She'eilat Ya'avetz siman 57.`,
  "5#_": `Beit Shmuel letter 2 and difficult behold Rashba wrote. NB in Mechilta thus Rashba also wrote — how giving should be kiddushin with this since for recipient it is not giving it is not kiddushin; but if he betroths with perutah on condition I will give you with this — if giving against will is called fulfilling condition — Maharit ruled one can say if he wants to give her worth of money and she does not want — it is not called fulfilling condition and clear; see teshuvah Beit Dinim Kiddushin siman 3.`,
  "6#_": `There letter 3 the Rav siman kiddushin. NB see below siman 30 in Beit Shmuel — intent of marketplace is only place of gathering merchants for business and at time of their gathering there for then it appears like acquisition of woman equal to other acquisitions there; see teshuvah Raneach part 1 siman 85; and regarding kiddushin at night see Sha'ar HaMelekh beginning Laws of Divorce.`,
  "7#_": `Seif 4 and he did not say to me she is not betrothed. NB even though she is already matchmade to him. Teshuvah Tashbetz part 4 section 2 siman 4; and teshuvah Maharit siman 127.`,
  "8#_": `There about matters of kiddushin the Rav is betrothed. NB and if he spoke with her on matter of kiddushin; but not to whom or he said "You are betrothed" and did not say "to me" and afterward said "You are my rib." Per my humble opinion it is kiddushin for from force of his words first about matters of kiddushin she understands "my rib" is language of kiddushin and automatically she knew he betroths her for himself from language "my rib" for he speaks on his own behalf.`,
  "9#_": `Beit Shmuel letter 19 R' Yehudah of Orleans is stringent. NB brought in Beit Yosef siman 136.`,
  "10#_": `Seif 8 it is doubt kiddushin. NB and if the betrother was 13 years and they examined and did not produce — Beit Shmuel; even though biblically we are concerned lest hairs fell nevertheless one can say it is double doubt since kiddushin themselves are also only doubt — see teshuvah Maharival part 1 23 siman 13 and teshuvah Shach part 2 siman 128.`,
});

p("siman_027/turei-zahav/part-001.txt", "turei-zahav", {
  "1#א": `And provided she understand — Beit Yosef wrote this does not refer to language "You are betrothed to me" for all know this is language of kiddushin; and if she says she did not know this is language of kiddushin she is not believed — except on other languages it refers end quote; and other languages Beit Yosef cited therefore meaning what Tur wrote after "You are betrothed" namely "my betrothed to me my wife" — and this is certainly wondrous for those languages are more explicit for kiddushin than language "betrothed" — especially "be my wife"; and further Beit Yosef wrote after this nearby there is dispute between Ran and Maggid Mishneh and between Rosh and Ran; nevertheless they wrote and in other languages that are clear to us above that help such as "my purchase" "acquired to me" and the others — specifically when he spoke with her about matters of her get and kiddushin she knew what he said; or she said she accepted for kiddushin — if not so she is not betrothed except per her knowledge end quote; implies in what is clear to us that helps she must understand; and Rosh wrote these languages are clear language of kiddushin — it is not in his power to say "I did not know they are language of kiddushin" end quote; implies in language clear that helps even if she says she does not recognize — she is betrothed; and perforce Beit Yosef distinguished between man and woman — for man it helps and for woman not; and she must say she recognizes; and wonder on the appearance in Rosh's words for plain language that helps per Beit Yosef's view even if he says he does not recognize — how possible to say thus for even woman's intent we require for kiddushin and all the more man's intent; and further since Rosh wrote it is not in his power etc. implies if we knew certainly he does not recognize these languages for kiddushin she would not be betrothed; and if so we do not believe him he did not know and we establish her as certainly betrothed; and automatically if she accepted kiddushin from another no get needed; and he speaks truth he did not know for condition is needed to inform us these are language of kiddushin — is it that all women are learned and know what was conditioned they know and teach us? Rather it appears clear matter there is distinction between plain ones meaning what is plain even in eyes of women such as betrothed engaged be my wife — we say certainly he and she understood; but in language "acquired to me" "my purchase" "in my possession" and similar — Torah needed to inform us it helps in this certainly she must understand; or if he speaks first about matters of get and kiddushin; and in these specifically Ran and Maggid Mishneh discuss as he cited these languages in Ran's words; and also Rosh holds so and he did not say these languages are clear to us regarding what is clear to us and not to her or him — for this certainly not; rather his intent in languages clear to us that he and she recognize them they are language of kiddushin — whether because this is regular in everyone's mouth or from another reason — in this we do not believe to say he did not know and make from this doubt; or one of them wants to uproot kiddushin; and this proves we require it be clear to us they know — for otherwise Rosh would write many cases even if he does not recognize it helps except plain this not; and if so also Tur's words are explained what he wrote "and must understand" — this refers to what is nearby language he wrote "and in every language whose meaning" etc. — on this he says she must understand this is language of kiddushin and it does not suffice that it is truly language of kiddushin in that place for some people of that place; and if he spoke with her first about matters of kiddushin even if certainly she does not understand she is betrothed — for he should pay attention to his words he intends for kiddushin for he spoke with her from this beginning; rather certainly she resolved herself for this even though she does not understand the language and it is truly language of kiddushin; and there is no distinction between man and woman. And further per my humble opinion even in language clear to all if she is recognized and says she does not recognize — she did not make herself a piece of prohibition regarding if she accepts kiddushin from another to require get from both since she would say she did not understand kiddushin; but whenever she returns and says she truly understood and gives excuse why she first said she did not understand — she is believed; unlike in matter not plain to her but plain to us — certainly complete doubt whenever he did not speak with her first about her kiddushin and needs get from both; and if known to us certainly this woman did not truly understand even language "betrothed to me" — certainly there is no kiddushin at all; and all this does not apply if he betroths under chuppah per customs for she knows she enters for kiddushin — all this plain per my humble opinion.`,
  "1#ב": `Rather whoever speaks with others before her suffices — such should read; and likewise in Mordekhai beginning Kiddushin; but statement of others alone not; and even her statement alone not without his statement; and on what is written siman 29 seif 2; and it appears to me further must read also in Mordekhai he speaks and not they speak for woman even if she takes it suffices as brought in hagahah Mordekhai end Gittin folio 248; and in Darkei Moshe they only brought he speaks with others in her presence.`,
  "2#א": `If she understood his words — he did not come to teach except to exclude if certainly she did not understand — this certainly even saying "You are betrothed to me" she is not believed; rather he teaches we establish her as understanding by default and it is not in her power to say she did not understand; but in these languages mentioned in this seif she must be that she understands or they spoke first etc.; and therefore it appears this matter does not refer to what is mentioned "You are my wife" for this certainly is like "You are betrothed" and even better; and likewise Ran from whom this law is written such as "my purchase" or "acquired to me" and other language etc. — behold he did not cite "You are my wife" mentioned at first and cited what follows — but to teach it refers only to other languages not so plain but plain to us as above.`,
  "2#ב": `But the man is not believed — very wondrous what distinction between man and woman; and he cited from Beit Yosef's explanation to Rosh; and already (explained) (should read we explained) nearby there is no distinction between them in truth — see there.`,
  "3#א": `You are my married woman etc. Reason in Rashba — if he says "You are my married woman" we did not hear she shall be betrothed for she is not called married until she has intercourse or enters chuppah end quote; and if so what difference from what is written afterward for love and affection etc. meaning for there be love and affection afterward — here too it is found she will be his marriage afterward; there it does not contradict law of intent for also law teaches thus that after accepting kiddushin love begins between them; unlike here it contradicts law of intent he says in accepting kiddushin she will be married and this is only nissuin which is completely separate act — therefore there is no kiddushin at all; but requires examination what difference from "set apart for me" which is language of kiddushin; and Rashi explained because it is written "and they shall be one flesh" and this applies only after nissuin; and nevertheless it helps since his intent is to come to that and we do not say his language contradicts my intent for language implies doubt kiddushin; rather she becomes set apart; here too in "my married woman" requires examination; and it appears this is not certainly language there is no kiddushin but doubt; and likewise Maharach z"l wrote one can explain Rashba's words as language of doubt kiddushin.`,
  "3#ב": `He gave to her in silence etc. Kiddushin — per my humble opinion plain there is deficiency here and must be doubt kiddushin since in essence of kiddushin there is no testimony for they cannot testify here on thought; and we require in kiddushin two witnesses for matter of nakedness is not less than two; rather certainly he speaks doubt kiddushin; and likewise implied explicitly in Mordekhai end chapter HaIsh Mekadesh who said there kiddushin nevertheless requires get — implies stringently only; but if she accepted kiddushin from another certainly needs get also from him; except nevertheless I have room to investigate these Mordekhai words who wrote there in name of teshuvah Maharam and Beit Yosef brings it thus: or even if he did not speak with her at all but only at time he gave her it was in his heart for kiddushin and if she accepted for kiddushin kiddushin nevertheless requires get; and although we say chapter HaIsh Mekadesh and in all of them even if she said in her heart she would be betrothed to him she is not betrothed for matters of heart are not matters — I am different there since he conditioned it is not in her power to uproot his condition; but here no less than resolving in his heart to take out wheat bread and took out bread simply they follow his thought and it is forbidden only wheat; and although regarding those men who bought property with intent to ascend to Israel we do not say so — I am different there for they follow mind of buyer; and further it appears to me since he said I give to you for love and affection etc. end quote; and great wonder to me in what he wrote I am different there he conditioned etc. for in chapter HaIsh Mekadesh there (Kiddushin folio 50) it says from where to Rava matters of heart are not matters — Abaye said from here even though she said in her heart she would be betrothed etc.; and they challenge and perhaps I am different there since he conditioned it is not in her power to uproot his condition — found what Rava said matters of heart are not matters means even where he does not uproot his condition; and if so learn from Rava everywhere matters of heart are not matters; and good question to me explained there afterward he learns from one who said to his agent bring me from the unconsecrated even though he said in his heart it was only idolatry etc. and this is because matters of heart are not matters; and there was no condition for even though he said to him bring me from unconsecrated it was not diminished thereby he would not bring from elsewhere as we say in HaMafkid folio 42 he said to him from this pile and from this not — and if so we saw Rava's words matters of heart are not matters means even where he does not uproot condition and estimation of buyer's mind is not relevant as branches in teshuvah Maharam — also very wondrous what he wrote in the teshuvah here no less than thought regarding wheat bread and took out bread simply — certainly less here for there at least there is speech causing prohibition namely he took out bread simply except there is implication all bread except through his thought we explain speech he said specifically on wheat; found they do not follow thought but regarding speech of prohibition; unlike kiddushin where there is no speech at all except giving ring and there is no kiddushin except thought for kiddushin — rather mere gift we consider it and essence of kiddushin from thought this certainly does not help; and further wonder from this in first chapter Kiddushin folio 5 in baraitta how with money etc. for first answer that resolves he gave and she said is not kiddushin at all plainly — question why not at least doubt kiddushin for her statement is worse than her silence and she intended for kiddushin helps for Maharam mentioned; and why does it not help also in her statement; and for second answer in he gave and she said it is doubt kiddushin — meaning specifically at least she said language of kiddushin; but without her saying at all not kiddushin from thought; and if so question on Maharam why silence helps for her from side of thought; and further question from what is written first chapter folio 6 shall we say when he does not speak with her first about matters of kiddushin from where would she know and they do not answer such as she admits she accepted for kiddushin; and likewise explained in Maggid Mishneh chapter 3 Laws of Marriage thus: and if they were not engaged at all in this and he gave her money simply she is not betrothed on basis he says he intended to betroth her end quote; and this discusses even if she too intended thus — for otherwise plain she is not betrothed; and I know I am not fit to decide even on students of Maharam — how much more on him; nevertheless I say Maharam did not rely there at all on ruling but on what is written afterward; and it appears since he said in love in affection there is language of kiddushin and Rama who copied beginning of Maharam's words did not fulfill obligation of explanation except since it emerged from Maharam's mouth to be stringent — who will raise head to be lenient.`,
  "3#ג": `Must return and take etc. Thus it is regarding get in first chapter Gittin folio 5 one who brings get and did not say it was written etc. the child is not mamzer — how shall he act? He takes it from her and returns and gives it to her before two and says etc.; but requires examination for granted regarding get he must say at time of giving specifically and it does not help if get was already in her hand as deposit — therefore no remedy except returning and taking; but regarding kiddushin that helps if money was already in deposit in her hand as written siman 28 seif 6 saying be betrothed to me with deposit in your hand and she says yes — if so here too let us say since first kiddushin is nothing the money is at least as deposit in her hand and she must return to him; and why does it not help if afterward he says to her be betrothed to me with money you gave me before and it is in your hand and she says yes; requires examination; and on what is written siman 31 seif 29.`,
  "5#_": `As kiddushin etc. Reason in Beit Yosef in name of Ribash — since it is mentioned he gives to her as kiddushin already appears from his language he is betrother and she betrothed — a person does not abandon his own mitzvah and throws on his fellow; and even if we knew he became agent for another nevertheless we say a person does not abandon what is incumbent upon him; and afterward Beit Yosef wrote in name of R' Yitzchak bar Rav in name of Rav Doran saying take this ring kiddushin for your daughter is nothing for he does not prove in these words the woman is betrother end quote; and apparently implies here there is dispute — for Ribash also here she is betrothed for certainly he performs mitzvah incumbent upon him; except one can distinguish between them — specifically in that Ribash case he said "I am giving to you" implying he is giver and betrother unlike in the second case of saying only take for you and he did not say from me; and if so here if he said behold it is yours as kiddushin it would not be as saying to me; and in hagahah Mordekhai end Gittin wrote incident with one young man speaking with one woman to lend money on one ketav etc. and afterward said to her do you wish to be betrothed with it if I give it to you; she began (to jest) and he returned and said to her behold it is yours for kiddushin literally with this law he said to her and did not say you are betrothed to me with this ketav; and behold the giver was inclined to permit her since he did not say to me; and it is wondrous who is worse than those who were silent and did not say for kiddushin that helps since he spoke first about matters of kiddushin etc.; and here too behold he spoke with her as he asked above end quote; and afterward wrote and further it appears to me even if he did not say at first his words do you wish to be betrothed with it — correct to be stringent etc. end quote; and this is from reason there are poskim presumptive evidence that does not prove are presumptive evidence; and this is like some are stringent Rama wrote above nearby even if he did not say to me; and here too even if he did not say I am giving to you but behold to you as kiddushin — be stringent in these kiddushin.`,
  "9#_": `And betroth yourself to me — in Gemara it is also thus she said yes; and apparently difficult why need I truly this statement for speech does not depend on her but specifically on his statement; and this is truly reason of "some are stringent" Rama brings on this; and it appears plain giving is for benefit of recipient and even with important person and not benefit of giver; except there are some people who have benefit to giver that recipient receives from important person — therefore with woman it is not kiddushin presumably with important person for not every woman seeks to marry Torah scholar; rather whenever we see clearly she pursues afterward meaning she says at time of giving money she has benefit from this — then his statement afterward with this helps; and likewise Rambam chapter 5 as Beit Yosef brings; and in teshuvah Rashba siman 213 also brings we require she say "and I betroth myself to you" from reason he cited; except he wrote there for Rambam her statement first is not needed; and certainly different version in Rambam; except Tur holds her statement first does not depend at all — even if she gave simply and he said there is distinction if he is important she is betrothed; and that which Gemara folio 7 asks Rava "Take a maneh and I will betroth myself to you" what is law — meaning since she said first there Rava said give maneh to so-and-so and I will betroth myself to you — betrothed from law of guarantor etc.; and there there is necessity she say first "and I will betroth myself to you" for with this she transfers herself as brought there — therefore Rava asks afterward also in this if she said "and I will betroth myself to you" whether there is also acquisition here; and plain there is distinction between important person; and if so no need at all for her statement first "and I will betroth myself to you" as Tur's reasoning above; except he wrote Rambam disagrees with Rif and Rosh and Rambam holds no distinction between important person or not; and already Beit Yosef seized on him and wrote also Rambam holds this distinction except he did not need to mention it since he mentioned elsewhere; and as Beit Yosef seized on him; and there are those who want to settle Tur's words he brings dispute of Rambam regarding he holds important person does not help unless she says first "and I will betroth myself to you" specifically and Tur does not hold so as we mentioned; and impossible to say thus for Tur concluded language and first reasoning is Rif's reasoning and likewise impossible z"l end quote; and in truth Rif is mentioned only as in Gemara namely in baraitta she gave and he said it is doubt and did not mention there it helps with important person; and below regarding word conversely he wrote in she said first "and I will betroth myself to you" then important person helps; and if so it is like Rambam except in Asheri he also wrote above in she gave and he said thus: if not with important person as he says below end quote; and certainly one can explain his words in what he says below namely if she said first "and I will betroth myself to you"; and we have no need to make dispute for nothing between Rambam and Rosh.`,
});

